<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { ElMessage,ElMessageBox } from 'element-plus'; import { apiGet,apiPatch } from '../api/client'; import KpiGrid from '../components/KpiGrid.vue'; import PageHeader from '../components/PageHeader.vue'; import type { UserItem } from '../types/admin'
import { useAuthStore } from '../stores/auth'; const auth=useAuthStore()
const items=ref<UserItem[]>([]);const loading=ref(true);const keyword=ref('');const status=ref('')
const filtered=computed(()=>items.value.filter(x=>(!keyword.value||`${x.nickname}${x.phone}${x.cityName}`.toLowerCase().includes(keyword.value.toLowerCase()))&&(!status.value||x.status===status.value)))
const kpis=computed(()=>[{label:'总用户',value:items.value.length,delta:'数据库总量'},{label:'正常用户',value:items.value.filter(x=>x.status==='normal').length,delta:'当前可用'},{label:'总收藏',value:items.value.reduce((s,x)=>s+x.favoriteCount,0),delta:'用户行为'},{label:'封禁中',value:items.value.filter(x=>x.status==='banned').length,delta:'需关注',warn:true}])
async function load(){loading.value=true;try{items.value=await apiGet<UserItem[]>('/admin/users')}finally{loading.value=false}}
async function toggle(tableRow:unknown){const row=tableRow as UserItem;const next=row.status==='normal'?'banned':'normal';await ElMessageBox.confirm(`确认${next==='banned'?'封禁':'解禁'}用户「${row.nickname}」？`,'账号状态',{type:'warning'});await apiPatch(`/admin/users/${row.id}/status`,{status:next});ElMessage.success('用户状态已写入数据库');await load()}
onMounted(load)
</script>
<template><PageHeader title="用户管理" group="用户与内容" description="查询用户资料、收藏与内容数量"><el-button :loading="loading" @click="load">刷新</el-button></PageHeader><KpiGrid :items="kpis" :loading="loading"/><section class="panel"><div class="panel__toolbar"><div class="panel__filters"><el-input v-model="keyword" clearable placeholder="昵称、手机号、城市…" style="width:260px"/><el-select v-model="status" clearable placeholder="全部状态" style="width:130px"><el-option label="正常" value="normal"/><el-option label="封禁" value="banned"/></el-select></div><span class="muted">{{filtered.length}} 位用户</span></div><el-table :data="filtered" v-loading="loading"><el-table-column label="用户" min-width="180"><template #default="{row}"><div class="route-name"><el-avatar :size="36">{{row.nickname.slice(0,1)}}</el-avatar><div><strong>{{row.nickname}}</strong><small>{{row.id}}</small></div></div></template></el-table-column><el-table-column prop="phone" label="手机号" width="140"/><el-table-column prop="cityName" label="城市" width="100"/><el-table-column label="注册时间" width="130"><template #default="{row}">{{new Date(row.createdAt).toLocaleDateString('zh-CN')}}</template></el-table-column><el-table-column label="最后活跃" width="170"><template #default="{row}">{{new Date(row.lastActiveAt).toLocaleString('zh-CN',{hour12:false})}}</template></el-table-column><el-table-column label="动态 / 收藏" width="120"><template #default="{row}">{{row.postCount}} / {{row.favoriteCount}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='normal'?'success':'danger'">{{row.status==='normal'?'正常':'已封禁'}}</el-tag></template></el-table-column><el-table-column v-if="auth.hasPermission('user:ban')" label="操作" width="110"><template #default="{row}"><el-button size="small" :type="row.status==='normal'?'danger':'success'" plain @click="toggle(row)">{{row.status==='normal'?'封禁':'解禁'}}</el-button></template></el-table-column></el-table></section></template>
